sysevent_script_action.script:
// current: GlideRecord - event scheduled on behalf of (incident for example) 
// event: GlideRecord - sysevent that caused this to be invoked

queueNextImport(
    current /* New file is parked here */ ,
    event.parm1 /* New file */ );

function queueNextImport(current, attachment_sys_id) {
    // A new data file has arrived and is parked on "Vendor Data Queue".

	// Queue the file up for import via data source "Vendor Data", unless...

    // ...Exit if there is a Scheduled Data Import for this data source
	// with a future run date.
    var util = new x_42999_import_v_0.VendorDataUtils();
    var gdtNow = new GlideDateTime();
    var scope = gs.getCurrentApplicationId();
	var activeOnly = true;
    var answer = util.hasScheduledImportAfter(scope, "Vendor Data", activeOnly, gdtNow);
	if(answer) {
		gs.info("There is an existing scheduled import for this data. Exiting.");
		return;
	}

	// Copy all attachments from "Vendor Data" to "Vendor Data Archive",
	// and remove originals
	util.shiftAttachments("Vendor Data", "Vendor Data Archive", true);

	// Create a Scheduled Data Import for Vendor Data, set it to run
	// soon.


    // Update the run date on Vendor Data to +1 minute
    // var gr_import = new GlideRecord("scheduled_import_set");
    // gr_import.setValue("sys_scope", gs.getCurrentApplicationId());
    // gr_import.setValue("name", "Vendor Data");
    // gr_import.query();
    // if (gr_import.next()) {
    //     gdt = new GlideDateTime();
    //     gdt.addSeconds(60);
    //     gr_import.setValue("run_start", gdt);
    //     gr_import.update();
    // }

}
